export const DEFAULT_UI_LANGUAGE: UiLanguage = 'en';

export function normalizeUiLanguage(value?: string | null): UiLanguage {
  if (value === 'zh_hant' || value === 'zh_hans' || value === 'en') return value;
  return DEFAULT_UI_LANGUAGE;
}

