export type Translator = (key: TranslationKey) => string;

const LANGUAGE_OVERRIDES: Record<UiLanguage, Partial<Record<TranslationKey, string>>> = {
  zh_hant: { sortByOldest: '最早加入', sortByTitleDesc: '標題 Z–A', sortBySource: '來源 A–Z', sortByModel: '模型 A–Z' },
  zh_hans: { sortByOldest: '最早加入', sortByTitleDesc: '标题 Z–A', sortBySource: '来源 A–Z', sortByModel: '模型 A–Z' },
  en: {},
};

export function makeTranslator(language: UiLanguage): Translator {
  return (key: TranslationKey) => LANGUAGE_OVERRIDES[language][key] || TRANSLATIONS[language][key] || TRANSLATIONS.en[key] || key;
}
